CustomField.formula:
IF(ISBLANK(HistoricalFlow__c),

IF(
  OR(
    LOWER(TEXT(Unit__r.Phase__r.Is_Reservation_Form_Required__c)) = "no"
  ),
  /* Reservation NOT required (or blank) */
  IF(
    ISBLANK(Opportunity__r.BrokerAgency__c),
    "SPA Without Broker Form",
    "SPA With Broker Form"
  ),
  /* Reservation required */
  IF(
    OR(
    LOWER(TEXT(Unit__r.Phase__r.Is_Reservation_Form_Required__c)) = "yes",
    ISBLANK(TEXT(Unit__r.Phase__r.Is_Reservation_Form_Required__c))),
    IF(
      ISBLANK(Opportunity__r.BrokerAgency__c),
      "Reservation Without Broker Form",
      "Reservation With Broker Form"
    ),
    /* Fallback */
    ""
  )
),
HistoricalFlow__c

)
